#!/usr/bin/env bash
# Phase 4 of the K2.6 plan (../runbook.md). Runs one config A/B (baseline vs
# TokenSpeed-variant) and saves outputs side-by-side.
#
# Usage:
#   ./run_bench.sh <config.yml> [<concurrency>] [<dataset.txt>]
#
# Defaults:
#   concurrency  → parsed from config filename (e.g. conc16 -> 16) or 1
#   dataset      → /scratch/runs/k2.6-spike/datasets/synth_<isl><osl>_<N>.txt,
#                  auto-generated by trtllm-bench prepare-dataset if missing.
#
# Examples:
#   ./run_bench.sh ../bench-config.yml                       # 1k/1k TP4 conc=1
#   ./run_bench.sh ../bench-1k1k_tp4_conc16.yml 16           # explicit conc
#   ./run_bench.sh ../bench-60k1k_tp8_conc1_mtp3_multiturn.yml 1 \
#       /scratch/runs/k2.6-spike/datasets/multiturn_replay.jsonl
#
# Spike-step-7 warning: rc14 has a q_len_per_req = 1 - input_length bug under
# TRTLLM_ENABLE_TRTLLM_GEN_ATTENTION=1 × trtllm-bench. If both base and ts
# fail with the SAME negative shape error, this is the bug — fall back to
# verify_kernel_swap.sh-style nsys per-iter measurement on quickstart_advanced.

set -euo pipefail

CONFIG="${1:?usage: run_bench.sh <config.yml> [<concurrency>] [<dataset>]}"
[[ -f "$CONFIG" ]] || { echo "config not found: $CONFIG" >&2; exit 1; }
CONFIG_NAME="$(basename "$CONFIG" .yml)"

# Parse concurrency: explicit arg > parsed from filename > default 1.
CONC="${2:-}"
if [[ -z "$CONC" ]]; then
    if [[ "$CONFIG_NAME" =~ conc([0-9]+) ]]; then
        CONC="${BASH_REMATCH[1]}"
    else
        CONC=1
    fi
fi

# Parse ISL/OSL from filename for dataset auto-gen (e.g. 1k1k -> 1024/1024,
# 60k1k -> 61440/1024, 8k1k -> 8192/1024). Default 1k/1k.
ISL=1024; OSL=1024
if [[ "$CONFIG_NAME" =~ ([0-9]+)k([0-9]+)k ]]; then
    A="${BASH_REMATCH[1]}"; B="${BASH_REMATCH[2]}"
    case "$A" in 60) ISL=61440;; *) ISL=$((A*1024));; esac
    OSL=$((B*1024))
fi

CONTAINER="${CONTAINER:-tokenspeed-spike-k26}"
MODEL_PATH="${MODEL_PATH:-/scratch/hf-cache/models--nvidia--Kimi-K2-Thinking-NVFP4}"
RUN_DIR="/scratch/runs/k2.6-spike/phase4-bench/$CONFIG_NAME"
NUM_REQ="${NUM_REQ:-$((CONC * 16))}"   # 16× concurrency for steady state

DEFAULT_DATASET="/scratch/runs/k2.6-spike/datasets/synth_${A:-1}k${B:-1}k_${NUM_REQ}.txt"
DATASET="${3:-$DEFAULT_DATASET}"

# Copy config into container-visible scratch so trtllm-bench can read it.
CFG_IN_CTR="/scratch/runs/k2.6-spike/configs/$CONFIG_NAME.yml"
docker exec "$CONTAINER" mkdir -p "$(dirname "$CFG_IN_CTR")" "$RUN_DIR" \
    "/scratch/runs/k2.6-spike/datasets"
docker cp "$CONFIG" "$CONTAINER:$CFG_IN_CTR"

docker exec "$CONTAINER" bash -c "
    set -euo pipefail
    MODEL=\$(ls -d $MODEL_PATH/snapshots/* 2>/dev/null | head -1)
    if [[ -z \"\$MODEL\" ]]; then
        echo 'ERROR: no K2.6 snapshot under $MODEL_PATH/snapshots/' >&2
        exit 1
    fi
    echo \"[bench] config=$CONFIG_NAME conc=$CONC isl=$ISL osl=$OSL model=\$MODEL\"

    # Generate synthetic dataset on demand (skip if user passed an explicit one).
    if [[ ! -f \"$DATASET\" && \"$DATASET\" == *synth_* ]]; then
        echo \"[bench] generating synthetic dataset $DATASET\"
        trtllm-bench --model nvidia/Kimi-K2-Thinking-NVFP4 --model_path \"\$MODEL\" \
            prepare-dataset \
                --tokenizer \"\$MODEL\" \
                --stdout token-norm-dist \
                --input-mean $ISL --input-stdev 0 \
                --output-mean $OSL --output-stdev 0 \
                --num-requests $NUM_REQ > \"$DATASET\"
    fi

    for VARIANT in base ts; do
        if [[ \$VARIANT == base ]]; then TS=0; else TS=1; fi
        LOG=$RUN_DIR/\${VARIANT}.log

        echo \"[bench] running \$VARIANT (TLLM_TOKENSPEED_MLA=\$TS) -> \$LOG\"
        TRTLLM_ENABLE_TRTLLM_GEN_ATTENTION=1 TLLM_TOKENSPEED_MLA=\$TS \
            trtllm-bench --model nvidia/Kimi-K2-Thinking-NVFP4 \
                --model_path \"\$MODEL\" \
                throughput --dataset \"$DATASET\" \
                --extra_llm_api_options \"$CFG_IN_CTR\" \
                --concurrency $CONC \
                > \"\$LOG\" 2>&1 || {
                    echo \"  WARN: \$VARIANT failed; tail of log:\"
                    tail -20 \"\$LOG\"
                }
    done

    echo
    echo \"=== A/B summary (per-token latency from log) ===\"
    for VARIANT in base ts; do
        LOG=$RUN_DIR/\${VARIANT}.log
        printf \"  %-4s  \" \"\$VARIANT\"
        if grep -qE 'Per User Output (Speed|Throughput)' \"\$LOG\"; then
            grep -E 'Per User Output|Token Throughput|Time To First|Inter Token' \"\$LOG\" \
                | tail -6 | tr '\\n' '|' | sed 's/|/  /g'
            echo
        else
            echo \"(no perf summary — likely failed)\"
        fi
    done
    echo \"Full logs in $RUN_DIR/{base,ts}.log\"
"
